using System.Text.RegularExpressions;

namespace CnGalWebSite.MainSite.Shared.Components.Features.Examine;

public static partial class RecordHtmlDiff
{
    public static string Build(string? before, string? after)
    {
        before ??= string.Empty;
        after ??= string.Empty;
        if (string.Equals(before, after, StringComparison.Ordinal)) return after;

        // Mark source ins/del elements before diffing so only wrappers generated by the
        // comparison can be hidden or highlighted by the side-specific styles.
        var markedBefore = MarkSourceChanges(before);
        var markedAfter = MarkSourceChanges(after);
        var diff = string.IsNullOrWhiteSpace(markedBefore)
            ? $"<ins>{markedAfter}</ins>"
            : string.IsNullOrWhiteSpace(markedAfter)
                ? $"<del>{markedBefore}</del>"
                : new HtmlDiff.HtmlDiff(markedBefore, markedAfter).Build();
        return RemoveSourceMarkers(MarkGeneratedChanges(diff));
    }

    private static string MarkSourceChanges(string html) =>
        SourceChangeTag().Replace(html, match =>
            $"<{match.Groups[1].Value} data-record-source='true'");

    private static string MarkGeneratedChanges(string html) =>
        GeneratedChangeTag().Replace(html, match =>
        {
            var tag = match.Groups[1].Value;
            var marker = string.Equals(tag, "ins", StringComparison.OrdinalIgnoreCase)
                ? "record-diff-inserted"
                : "record-diff-deleted";
            var attributes = match.Groups[2].Value;
            var classMatch = ClassAttribute().Match(attributes);
            if (classMatch.Success)
            {
                var quote = classMatch.Groups[1].Value;
                var classes = classMatch.Groups[2].Value;
                if (!classes.Split(' ', StringSplitOptions.RemoveEmptyEntries).Contains(marker, StringComparer.Ordinal))
                {
                    attributes = attributes.Remove(classMatch.Index, classMatch.Length)
                        .Insert(classMatch.Index, $"class={quote}{classes} {marker}{quote}");
                }
                return $"<{tag}{attributes}>";
            }
            return $"<{tag} class='{marker}'{attributes}>";
        });

    private static string RemoveSourceMarkers(string html) => SourceMarker().Replace(html, string.Empty);

    [GeneratedRegex(@"<(ins|del)(?=[\s>])", RegexOptions.IgnoreCase)]
    private static partial Regex SourceChangeTag();

    [GeneratedRegex(@"<(ins|del)(?![^>]*\bdata-record-source\b)([^>]*)>", RegexOptions.IgnoreCase)]
    private static partial Regex GeneratedChangeTag();

    [GeneratedRegex(@"\bclass\s*=\s*(['""])(.*?)\1", RegexOptions.IgnoreCase)]
    private static partial Regex ClassAttribute();

    [GeneratedRegex(@"\sdata-record-source\s*=\s*(['""])true\1", RegexOptions.IgnoreCase)]
    private static partial Regex SourceMarker();
}
